"use client";

import { useMemo, useState } from "react";
import { BarChart3 } from "lucide-react";
import { CapabilityTree } from "@/components/survey/CapabilityTree";
import { L3DetailDrawer } from "@/components/survey/L3DetailDrawer";
import { SurveyTabs } from "@/components/survey/SurveyTabs";
import { surveyData, surveyTabs } from "@/data/surveyData";
import type { L3DetailDraft, L3DetailState, SurveyNode } from "@/types/survey";

function collectInitialValues(nodes: SurveyNode[]) {
  const priorValues: Record<string, string> = {};
  const currentValues: Record<string, string> = {};
  const commentaryValues: Record<string, string> = {};
  const detailValues: Record<string, L3DetailState> = {};
  const expanded: Record<string, boolean> = {};

  const visit = (node: SurveyNode) => {
    if (node.prior !== undefined) {
      priorValues[node.id] = node.prior.toFixed(1);
    }

    if (node.current !== undefined) {
      currentValues[node.id] = node.current.toFixed(1);
    }

    if (node.commentary !== undefined) {
      commentaryValues[node.id] = node.commentary;
    }

    if (node.level === 3) {
      const current = node.current?.toFixed(1) ?? "";
      const commentary = node.commentary ?? "";

      detailValues[node.id] = {
        annualBudget: node.annualBudget ?? node.current ?? 0,
        commentary,
        current,
        deploymentModel: node.deploymentModel ?? "Hybrid",
        expectedSavings: node.expectedSavings ?? 0,
        hostingType: node.hostingType ?? "IaaS",
        riskLevel: node.riskLevel ?? "Medium",
        status: node.status ?? "In Production",
        strategicTechnology: node.strategicTechnology ?? false,
      };
    }

    if (node.children?.length) {
      expanded[node.id] = true;
      node.children.forEach(visit);
    }
  };

  nodes.forEach(visit);

  return { priorValues, currentValues, commentaryValues, detailValues, expanded };
}

function findSelectedContext(
  nodes: SurveyNode[],
  id: string | null,
  parents: string[] = ["Core Technology"],
): { breadcrumb: string[]; node: SurveyNode } | null {
  if (!id) {
    return null;
  }

  for (const node of nodes) {
    if (node.id === id && node.level === 3) {
      return { breadcrumb: parents, node };
    }

    if (node.children?.length) {
      const found = findSelectedContext(node.children, id, [...parents, node.name]);

      if (found) {
        return found;
      }
    }
  }

  return null;
}

function parseFormNumber(value: string, fallback: number) {
  const parsed = Number.parseFloat(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

export function SurveyCard() {
  const initialState = useMemo(() => collectInitialValues(surveyData), []);
  const [activeTab] = useState("core-technology");
  const [priorValues, setPriorValues] = useState(initialState.priorValues);
  const [currentValues, setCurrentValues] = useState(initialState.currentValues);
  const [commentaryValues, setCommentaryValues] = useState(
    initialState.commentaryValues,
  );
  const [detailValues, setDetailValues] = useState(initialState.detailValues);
  const [expanded, setExpanded] = useState(initialState.expanded);
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);

  const selectedContext = useMemo(
    () => findSelectedContext(surveyData, selectedNodeId),
    [selectedNodeId],
  );

  const handleToggle = (id: string) => {
    setExpanded((previous) => ({
      ...previous,
      [id]: !(previous[id] ?? true),
    }));
  };

  const handleCurrentChange = (id: string, value: string) => {
    setCurrentValues((previous) => ({
      ...previous,
      [id]: value,
    }));
  };

  const handlePriorChange = (id: string, value: string) => {
    setPriorValues((previous) => ({
      ...previous,
      [id]: value,
    }));
  };

  const handleCommentaryChange = (id: string, value: string) => {
    setCommentaryValues((previous) => ({
      ...previous,
      [id]: value,
    }));
  };

  const handleSelectNode = (node: SurveyNode) => {
    if (node.level === 3) {
      setSelectedNodeId(node.id);
    }
  };

  const handleSaveDetails = (id: string, draft: L3DetailDraft) => {
    setCurrentValues((previous) => ({
      ...previous,
      [id]: draft.current,
    }));
    setCommentaryValues((previous) => ({
      ...previous,
      [id]: draft.commentary,
    }));
    setDetailValues((previous) => {
      const existing = previous[id];

      return {
        ...previous,
        [id]: {
          commentary: draft.commentary,
          current: draft.current,
          deploymentModel: draft.deploymentModel,
          hostingType: draft.hostingType,
          strategicTechnology: draft.strategicTechnology,
          status: draft.status,
          annualBudget: parseFormNumber(
            draft.annualBudget,
            existing?.annualBudget ?? 0,
          ),
          expectedSavings: parseFormNumber(
            draft.expectedSavings,
            existing?.expectedSavings ?? 0,
          ),
          riskLevel: draft.riskLevel,
        },
      };
    });
    setSelectedNodeId(null);
  };

  return (
    <>
      <section className="overflow-hidden rounded-lg border border-survey-border bg-white shadow-card">
        <div className="flex items-start gap-3 border-b border-survey-border px-5 py-[18px]">
          <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-survey-orangeSoft text-survey-orange">
            <BarChart3 className="h-4 w-4" strokeWidth={2} />
          </div>
          <div className="min-w-0">
            <h2 className="text-[13px] font-semibold leading-4 text-[#0F172A]">
              Section 2 &middot; Working Data
            </h2>
            <p className="mt-1 text-[11px] leading-4 text-[#374151]">
              Enter current-year values. A warning appears when variance exceeds &plusmn;15%, and commentary becomes mandatory.
            </p>
          </div>
        </div>

        <SurveyTabs activeTab={activeTab} tabs={surveyTabs} />

        <CapabilityTree
          commentaryValues={commentaryValues}
          currentValues={currentValues}
          data={surveyData}
          expanded={expanded}
          priorValues={priorValues}
          selectedNodeId={selectedNodeId}
          onCommentaryChange={handleCommentaryChange}
          onCurrentChange={handleCurrentChange}
          onPriorChange={handlePriorChange}
          onSelectNode={handleSelectNode}
          onToggle={handleToggle}
        />
      </section>

      {selectedContext && selectedNodeId && detailValues[selectedNodeId] ? (
        <L3DetailDrawer
          breadcrumb={selectedContext.breadcrumb}
          commentary={commentaryValues[selectedNodeId] ?? ""}
          currentValue={currentValues[selectedNodeId] ?? ""}
          detail={detailValues[selectedNodeId]}
          key={selectedNodeId}
          node={selectedContext.node}
          onClose={() => setSelectedNodeId(null)}
          onSave={handleSaveDetails}
          priorValue={priorValues[selectedNodeId] ?? ""}
        />
      ) : null}
    </>
  );
}
